interface LGBMNode {
  split_feature?: number;
  threshold?: number;
  left_child?: LGBMNode;
  right_child?: LGBMNode;
  leaf_value?: number;
}

function evaluateNode(node: LGBMNode, features: number[]): number {
  if (node.leaf_value !== undefined) {
    return node.leaf_value;
  }
  if (node.split_feature === undefined || node.threshold === undefined) {
    return 0;
  }
  const val = features[node.split_feature];
  if (val <= node.threshold) {
    return node.left_child ? evaluateNode(node.left_child, features) : 0;
  } else {
    return node.right_child ? evaluateNode(node.right_child, features) : 0;
  }
}

export interface NQMLDualPrediction {
  probBuy: number;
  probSell: number;
}

/**
 * Inferência nativa ultra-rápida (< 0.08ms) executando ambos os modelos especialistas (COMPRA e VENDA).
 */
export function predictNQDualProbabilities(rawFeatures: number[]): NQMLDualPrediction {
  // 1. Escalar para COMPRA
  const scaledBuy = new Array(rawFeatures.length);
  for (let i = 0; i < rawFeatures.length; i++) {
    const c = NQ_ML_BUY_SCALER.center[i] ?? 0;
    const s = NQ_ML_BUY_SCALER.scale[i] ?? 1;
    scaledBuy[i] = s !== 0 ? (rawFeatures[i] - c) / s : 0;
  }

  let scoreBuy = 0;
  for (let t = 0; t < NQ_ML_BUY_TREES.length; t++) {
    scoreBuy += evaluateNode(NQ_ML_BUY_TREES[t] as LGBMNode, scaledBuy);
  }
  const probBuy = 1 / (1 + Math.exp(-scoreBuy));

  // 2. Escalar para VENDA
  const scaledSell = new Array(rawFeatures.length);
  for (let i = 0; i < rawFeatures.length; i++) {
    const c = NQ_ML_SELL_SCALER.center[i] ?? 0;
    const s = NQ_ML_SELL_SCALER.scale[i] ?? 1;
    scaledSell[i] = s !== 0 ? (rawFeatures[i] - c) / s : 0;
  }

  let scoreSell = 0;
  for (let t = 0; t < NQ_ML_SELL_TREES.length; t++) {
    scoreSell += evaluateNode(NQ_ML_SELL_TREES[t] as LGBMNode, scaledSell);
  }
  const probSell = 1 / (1 + Math.exp(-scoreSell));

  return { probBuy, probSell };
}

// Compatibilidade retroativa
export function predictNQProbability(rawFeatures: number[]): number {
  return predictNQDualProbabilities(rawFeatures).probBuy;
}
